// Bootstrap domain: the sentinel (GetNativeTerrain merges slots
// against -1) plus the one enumerator a consumer has needed so far.
// The full roster still gets its own header when more are wanted -
// that move is the wider change terrain.h describes, and this is not
// it.
// eTerrainWater and eTerrainRock are admitted on retail proof, not on the DC roster
// alone: terrain.h's ten-mask analysis recovers the permutation
// {Lava=7, Rock=9, Dirt=0, Snow=3, Rough=5, Swamp=4, Subterranean=6,
// Water=8, Grass=2, Sand=1} from iconwdgt's own .bss store addresses,
// and initialize.obj repeats the identical ordering independently
// (a chance agreement of two ten-element orderings is 1 in 10!). The
// SPELLING is the Dreamcast enum's (eTerrainDirt=0 ... eTerrainRock=9).
// town.obj's check_shipyard_square accepts a dock square only on terrain 8;
// mapcell.obj's is_diggable independently rejects both 8 and 9.
enum TTerrainType {
    TERRAIN_NONE = -1,
    // Terrain 7 is lava, byte-proven by terrain.h's ten-mask permutation
    // and needed by mapcell.obj's readMapLayer, which marks a cell
    // animated on terrain 7 or 8 and on any river or road.
    //
    // GATED, for the reason the EArtifactId placement note above gives:
    // armygrp.h sits inside initialize.cpp's include closure through
    // town.h, and adding this enumerator unconditionally takes
    // initialize_game_data 100.0 -> 96.09 through the include-set
    // sensitivity class - measured 2026-08-19, no semantic change
    // anywhere. The view macro keeps the extra symbol out of the TUs
    // that do not need it.
    eTerrainLava = 7,
    eTerrainWater = 8,
    eTerrainRock = 9
};

// The special-ground MODE GetArmyMorale/GetArmyLuck dispatch on (the
// dword param with sentinels 2..5): cursed ground zeroes the stat,
// holy ground/evil fog swing morale by town alignment, the clover
// field lifts neutral-town luck. NH3API terrain.hpp EMagicTerrain
// spellings; only the byte-proven sentinels are listed.
enum EMagicTerrain {
    MAGIC_TERRAIN_CURSED_GROUND = 0x2,
    MAGIC_TERRAIN_HOLY_GROUND = 0x3,
    MAGIC_TERRAIN_EVIL_FOG = 0x4,
    MAGIC_TERRAIN_CLOVER_FIELD = 0x5
};

// PROVEN layout (2026-08-04): Dreamcast CodeView class size 56 with
// armies @0 and numTroops @28, corroborated by retail codegen - the
// 7-slot loops and the CREATURE_NONE sentinel in
// GetNumArmies (0x44acc0) / IsMember (0x44ab80).
// PROVEN layout (2026-08-04): stride 116 from the retail index math
// (idx*29 dwords in HasAllUndead/get_AI_value), attributes @0x10 and
// AI_value @0x40 from the same bodies; field names are the NH3API
// roster, which lands exactly on those offsets with cost[7].
struct TCreatureTypeTraits {
    int townType;
    int level;
    const char* cSamplePrefix;
    const char* m_sprite_name;
    unsigned int attributes;
    const char* m_name;
    const char* m_plural_name;
    const char* special_ability;
    int cost[7];
    int baseFightValue;
    int AI_value;
    int growthRate;
    int horde_growth_rate;
    int hitPoints;
    int speed;
    int attackSkill;
    int defenseSkill;
    int damageLowBound;
    int damageHighBound;
    int numShots;
    int hasSpell;
    int wanderingLow;
    int wanderingHigh;
};
SIZE(TCreatureTypeTraits, 116);

// attributes bits proven by retail tests: 0x40000 by HasAllUndead
// (0x44ab20); 0x40 by GetAlignments (0x44abb0), which skips such
// creatures in the alignment census - the war-machine bit.
const unsigned int CTA_UNDEAD = 0x40000;
const unsigned int CTA_SIEGE_WEAPON = 0x40;
// 0x20000 zeroes a stack's morale outright (GetArmyMorale 0x44b11e) -
// the no-morale trait (undead/elemental/war-machine family).
const unsigned int CTA_NO_MORALE = 0x20000;

// Artifact ids as the IsWieldingArtifact gates surface them (NH3API
// artifact.hpp spellings; every name is corroborated by the byte-
// proven behavior at its call site). 0x54 zeroes POSITIVE morale
// (GetArmyMorale 0x44b23a); 0x55 zeroes luck for BOTH sides when
// either hero wields it (GetLuck 0x44b2e4). The rest are
// get_spell_work_chance's immunity gates: the eight pendants block
// exactly their lore spells, the Badge blocks the mind family, the
// Sphere of Permanence blocks Dispel, the Orb of Vulnerability makes
// work certain, and 0x86 - Power of the Dragon Father - blocks
// level<=4 spells (the decode note's "Orb of Inhibition" inference
// does not survive the NH3API roster: inhibition is 0x7e).
enum EArtifactId {
    // combatManager::can_cast_spells (0x41f890) gates a hero cast on
    // slot 0 and then refuses every cast when either combat hero
    // wields 0x7e - the pair the decode note above already calls out
    // (spellbook first, inhibition 0x7e).
    ARTIFACT_SPELLBOOK = 0x0,
    ARTIFACT_BADGE_OF_COURAGE = 0x31,
    ARTIFACT_SPIRIT_OF_OPPRESSION = 0x54,
    ARTIFACT_HOURGLASS_OF_THE_EVIL_HOUR = 0x55,
    // The two obstacle-penalty bows: combatManager::ShotIsThroughWall
    // (0x467510) waives the town-wall penalty for a shooter whose own
    // hero wields either of them, pushing 0x5b then 0x89 into
    // hero::IsWieldingArtifact. Exactly two artifacts in HoMM3 cancel
    // the obstacle/wall penalty - the Golden Bow and its combination
    // successor, the Bow of the Sharpshooter - so the semantics pin
    // the pairing. NH3API spellings; both values retail-proven by the
    // pushed immediates. (0x89 is also CREATURE_SHARPSHOOTER's id in
    // the unrelated creature domain - a coincidence of numbering, not
    // a shared enum.)
    ARTIFACT_GOLDEN_BOW = 0x5b,
    ARTIFACT_SPHERE_OF_PERMANENCE = 0x5c,
    ARTIFACT_ORB_OF_VULNERABILITY = 0x5d,
    ARTIFACT_PENDANT_OF_DISPASSION = 0x64,
    ARTIFACT_PENDANT_OF_SECOND_SIGHT = 0x65,
    ARTIFACT_PENDANT_OF_HOLINESS = 0x66,
    ARTIFACT_PENDANT_OF_LIFE = 0x67,
    ARTIFACT_PENDANT_OF_DEATH = 0x68,
    ARTIFACT_PENDANT_OF_FREE_WILL = 0x69,
    ARTIFACT_PENDANT_OF_NEGATIVITY = 0x6a,
    ARTIFACT_PENDANT_OF_TOTAL_RECALL = 0x6b,
    ARTIFACT_ORB_OF_INHIBITION = 0x7e,
    ARTIFACT_POWER_OF_THE_DRAGON_FATHER = 0x86,
    ARTIFACT_BOW_OF_THE_SHARPSHOOTER = 0x89
};

